INSERT INTO exercises (id, name, category, equipment, target, muscle_group, secondary_muscles, instructions_es, image_url, gif_url) VALUES
('0064', 'barbell one arm bent over row', 'back', 'barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una barra con una mano usando un agarre pronado. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y la cabeza en posición neutral. Tira de la barra hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0064-Jsgsc27.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0064-Jsgsc27.gif'),
('0065', 'barbell one arm floor press', 'upper arms', 'barbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho. Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0065-vtusOWT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0065-vtusOWT.gif'),
('0066', 'barbell one arm side deadlift', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra en una mano con un agarre pronado. Mantén la espalda recta y el core activado. Flexiona las caderas y baja la barra hacia el exterior de la pierna, manteniendo el brazo recto y el pecho elevado. Baja la barra tanto como puedas manteniendo una buena forma. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0066-2DxtqHL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0066-2DxtqHL.gif'),
('0067', 'barbell one arm snatch', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","forearms","core"}', 'Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Extiende las caderas, las rodillas y los tobillos de forma explosiva, impulsando la barra hacia arriba. Cuando la barra llegue a la altura del pecho, tira de ella hacia arriba con el brazo, manteniéndola cerca del cuerpo. Rota el codo por debajo de la barra y extiende el brazo completamente por encima de la cabeza, bloqueando el codo. Baja la barra de vuelta a la posición inicial de forma controlada. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0067-xHKN2s8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0067-xHKN2s8.gif'),
('0068', 'barbell one leg squat', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta un pie del suelo y extiéndelo hacia delante, manteniéndolo paralelo al suelo. Flexiona la pierna de apoyo y baja el cuerpo como si te sentaras en una silla, manteniendo el pecho elevado y la espalda recta. Baja hasta que el muslo quede paralelo al suelo, luego empuja con el talón para volver a la posición inicial. Repite el número de repeticiones deseado y luego cambia de pierna y repite.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0068-uKyN64F.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0068-uKyN64F.gif'),
('0069', 'barbell overhead squat', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves","core"}', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra con un agarre amplio, colocándola por encima de la cabeza con los brazos completamente extendidos. Activa el core y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con los dedos de los pies. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0069-gfk9kD4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0069-gfk9kD4.gif'),
('1411', 'barbell palms down wrist curl over a bench', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies planos sobre el suelo y los antebrazos apoyados sobre los muslos, con las palmas hacia abajo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros. Baja la barra hacia el suelo flexionando las muñecas, manteniendo los antebrazos fijos. Haz una pausa breve en la parte baja y luego levanta lentamente la barra extendiendo las muñecas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1411-yzYH9pI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1411-yzYH9pI.gif'),
('1412', 'barbell palms up wrist curl over a bench', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, con las palmas hacia arriba. Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1412-SJAA2IQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1412-SJAA2IQ.gif'),
('3017', 'barbell pendlay row', 'back', 'barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia delante desde las caderas manteniendo la espalda recta y el pecho elevado. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3017-r0z6xzQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3017-r0z6xzQ.gif'),
('1751', 'barbell pin presses', 'upper arms', 'barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Coloca una barra en un rack de potencia a la altura del pecho. Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1751-bndCa3Q.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1751-bndCa3Q.gif'),
('0070', 'barbell preacher curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte. Agarra la barra con un agarre supino, un poco más ancho que la separación de los hombros. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0070-qOgPVf6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0070-qOgPVf6.gif'),
('0071', 'barbell press sit-up', 'waist', 'barbell', 'abs', 'shoulders', '{"shoulders","chest"}', 'Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, apoyándola sobre el pecho. Activando el abdomen, levanta lentamente la parte superior del cuerpo del suelo, curvándote hacia adelante hasta que tu torso forme un ángulo de 45 grados. Haz una pausa por un momento en la parte superior, luego baja lentamente la parte superior del cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0071-wnEscH8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0071-wnEscH8.gif'),
('0072', 'barbell prone incline curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él. Sujeta una barra con un agarre supino, separado a la altura de los hombros. Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0072-WLvTAv5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0072-WLvTAv5.gif'),
('0073', 'barbell pullover', 'back', 'barbell', 'lats', 'chest', '{"chest","triceps"}', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre a la altura de los hombros y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales. Haz una pausa breve y luego levanta la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0073-i6LWjok.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0073-i6LWjok.gif'),
('0022', 'barbell pullover to press', 'back', 'barbell', 'lats', 'triceps', '{"triceps","chest","shoulders"}', 'Túmbate boca arriba en un banco con la cabeza en un extremo y los pies en el suelo. Sujeta una barra con un agarre pronado (palmas mirando hacia afuera) y extiende los brazos rectos por encima del pecho. Manteniendo los brazos rectos, baja la barra detrás de la cabeza con un movimiento en forma de arco hasta sentir un estiramiento en los dorsales. Haz una pausa breve, luego invierte el movimiento y empuja la barra de vuelta a la posición inicial por encima del pecho. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0022-znLogoF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0022-znLogoF.gif'),
('0074', 'barbell rack pull', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Coloca una barra en un soporte a la altura de la rodilla. Ponte de pie con los pies separados a la altura de los hombros, los dedos de los pies ligeramente hacia afuera. Flexiona las caderas y las rodillas para bajar y agarrar la barra con un agarre pronado, manos separadas a la altura de los hombros. Activa el core y levanta la barra extendiendo las caderas y las rodillas, llevando los hombros hacia atrás y apretando los glúteos en la parte alta. Baja la barra de vuelta a la posición inicial flexionando las caderas y las rodillas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0074-za9Ni4z.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0074-za9Ni4z.gif'),
('0075', 'barbell rear delt raise', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","rhomboids"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Levanta la barra hacia los lados, manteniendo los brazos rectos, hasta que queden paralelos al suelo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0075-Ln9iTbU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0075-Ln9iTbU.gif'),
('0076', 'barbell rear delt row', 'shoulders', 'barbell', 'delts', 'trapezius', '{"trapezius","rhomboids","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de la barra hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0076-S9zHIvU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0076-S9zHIvU.gif'),
('0078', 'barbell rear lunge', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Empieza de pie con los pies separados a la altura de los hombros y una barra apoyada sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0078-VaP75jl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0078-VaP75jl.gif'),
('0077', 'barbell rear lunge v. 2', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Da un paso hacia atrás con el pie derecho, apoyándote en la punta del pie. Flexiona ambas rodillas para bajar el cuerpo hasta que el muslo izquierdo quede paralelo al suelo. Empuja con el talón izquierdo para volver a la posición inicial. Repite con la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0077-62Nw60O.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0077-62Nw60O.gif'),
('0079', 'barbell revers wrist curl v. 2', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Manteniendo los antebrazos fijos, exhala y flexiona las muñecas hacia arriba tanto como sea posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0079-qDnGfDb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0079-qDnGfDb.gif'),
('2187', 'barbell reverse close-grip bench press', 'upper arms', 'barbell', 'triceps', 'chest', '{"chest","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo. Haz una pausa breve cuando la barra esté justo encima del pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2187-YqJw82s.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2187-YqJw82s.gif'),
('0080', 'barbell reverse curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Mantén los brazos superiores fijos y exhala mientras levantas la barra hacia arriba, contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras bajas lentamente la barra de vuelta a la posición inicial, manteniendo los brazos superiores fijos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0080-xNrS20v.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0080-xNrS20v.gif'),
('0118', 'barbell reverse grip bent over row', 'back', 'barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra con un agarre pronado, palmas hacia abajo, y las manos un poco más separadas que el ancho de los hombros. Inclínate hacia delante desde las caderas, manteniendo la espalda recta y el pecho elevado, hasta que el torso quede casi paralelo al suelo. Tira de la barra hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0118-SzX3uzM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0118-SzX3uzM.gif'),
('1256', 'barbell reverse grip decline bench press', 'chest', 'barbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que las caderas. Agarra la barra con un agarre invertido, un poco más ancho que la separación de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1256-DotAgEF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1256-DotAgEF.gif'),
('1257', 'barbell reverse grip incline bench press', 'chest', 'barbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Túmbate en el banco con los pies planos sobre el suelo. Agarra la barra con un agarre invertido, manos un poco más separadas que el ancho de los hombros. Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo. Haz una pausa breve cuando la barra toque el pecho. Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1257-DU7I633.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1257-DU7I633.gif'),
('1317', 'barbell reverse grip incline bench row', 'back', 'barbell', 'upper back', 'biceps', '{"biceps","forearms"}', 'Coloca un banco inclinado a un ángulo de 45 grados. Siéntate en el banco frente al respaldo con el pecho apoyado contra él. Sujeta la barra con un agarre invertido (palmas hacia abajo) y las manos un poco más separadas que el ancho de los hombros. Mantén la espalda recta y el core activado. Tira de la barra hacia la parte superior del abdomen, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1317-8d8qJQI.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1317-8d8qJQI.gif'),
('1721', 'barbell reverse grip skullcrusher', 'upper arms', 'barbell', 'triceps', 'forearms', '{"forearms"}', 'Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco. Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros. Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas. Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos. Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1721-yRLPCLu.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1721-yRLPCLu.gif'),
('0081', 'barbell reverse preacher curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0081-4LIG9xr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0081-4LIG9xr.gif'),
('0082', 'barbell reverse wrist curl', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre pronado, con las palmas hacia abajo. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia el cuerpo. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0082-LsZkfU6.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0082-LsZkfU6.gif'),
('0084', 'barbell rollerout', 'waist', 'barbell', 'abs', 'lower back', '{"lower back"}', 'Ponte de rodillas en el suelo y sujeta una barra con ambas manos, separadas a la altura de los hombros. Haz rodar la barra hacia delante, extendiendo los brazos y manteniendo el core activado. Continúa rodando hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve y luego haz rodar lentamente la barra de vuelta hacia las rodillas, manteniendo el control. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0084-7M66AVi.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0084-7M66AVi.gif'),
('0083', 'barbell rollerout from bench', 'waist', 'barbell', 'abs', 'shoulders', '{"shoulders","triceps"}', 'Empieza de rodillas en el suelo con una barra colocada sobre un banco frente a ti. Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros. Manteniendo el core activado y la espalda recta, haz rodar lentamente la barra hacia delante, extendiendo los brazos frente a ti. Continúa haciendo rodar la barra hacia delante hasta que el cuerpo esté completamente extendido y los brazos por encima de la cabeza. Haz una pausa breve en la posición de extensión total, luego haz rodar lentamente la barra de vuelta hacia el cuerpo, volviendo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0083-Gxg9lDc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0083-Gxg9lDc.gif'),
('0085', 'barbell romanian deadlift', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo. Siente el estiramiento en los isquiotibiales mientras bajas la barra. Cuando sientas el estiramiento en los isquiotibiales, empuja las caderas hacia delante y ponte de pie. Aprieta los glúteos en la parte alta del movimiento. Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0085-wQ2c4XD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0085-wQ2c4XD.gif'),
('0086', 'barbell seated behind head military press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y bájala a la altura de los hombros, detrás de la cabeza. Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0086-ngPpyRS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0086-ngPpyRS.gif'),
('0087', 'barbell seated bradford rocky press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente flexionados y apuntando hacia delante. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0087-0dCyly0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0087-0dCyly0.gif'),
('0088', 'barbell seated calf raise', 'lower legs', 'barbell', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Coloca la barra sobre los muslos y sujétala con firmeza con las manos. Manteniendo la espalda recta y el core activado, levanta los talones del suelo extendiendo los tobillos. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0088-ktsFQAZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0088-ktsFQAZ.gif'),
('1371', 'barbell seated calf raise', 'lower legs', 'barbell', 'calves', 'hamstrings', '{"hamstrings"}', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre los muslos. Coloca la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón. Baja los talones tanto como sea posible, sintiendo un estiramiento en las pantorrillas. Levanta los talones lo más alto posible, contrayendo las pantorrillas. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1371-ipvgBnC.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1371-ipvgBnC.gif'),
('1718', 'barbell seated close grip behind neck triceps extension', 'upper arms', 'barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante. Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza. Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1718-4CBIBOM.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1718-4CBIBOM.gif'),
('0089', 'barbell seated close-grip concentration curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros. Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti. Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0089-1V1gj1u.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0089-1V1gj1u.gif'),
('0090', 'barbell seated good morning', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Siéntate en un banco con los pies planos sobre el suelo y una barra apoyada sobre la parte superior de la espalda. Mantén la espalda recta y el pecho elevado. Inclínate lentamente hacia delante desde las caderas, bajando el torso hacia el suelo. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0090-d960PgE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0090-d960PgE.gif'),
('0091', 'barbell seated overhead press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta la barra con un agarre pronado, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante. Empuja la barra por encima de la cabeza extendiendo completamente los brazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0091-kTbSH9h.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0091-kTbSH9h.gif'),
('0092', 'barbell seated overhead triceps extension', 'upper arms', 'barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Siéntate en un banco con la espalda recta y los pies planos sobre el suelo. Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza. Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza. Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0092-5uFK1xr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0092-5uFK1xr.gif'),
('0094', 'barbell seated twist', 'waist', 'barbell', 'abs', 'obliques', '{"obliques","lower back"}', 'Siéntate en un banco plano con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con ambas manos frente al pecho, manteniendo los codos ligeramente flexionados. Activa el core y gira lentamente el torso hacia un lado, manteniendo la espalda recta. Haz una pausa breve al final del giro y luego rota lentamente de vuelta a la posición inicial. Repite el giro hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0094-dFSNDOA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0094-dFSNDOA.gif'),
('0095', 'barbell shrug', 'back', 'barbell', 'traps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a ti con un agarre pronado. Mantén los brazos rectos y la espalda recta durante todo el ejercicio. Levanta los hombros hacia las orejas lo más alto posible, apretando los trapecios en la parte alta. Mantén la posición por un momento y luego baja lentamente los hombros de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0095-dG7tG5y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0095-dG7tG5y.gif'),
('0096', 'barbell side bent v. 2', 'waist', 'barbell', 'abs', 'obliques', '{"obliques","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con ambas manos, con las palmas hacia abajo. Mantén la espalda recta y el core activado durante todo el ejercicio. Inclina lentamente el torso hacia el lado derecho, bajando la barra hacia tu rodilla derecha. Haz una pausa breve y luego vuelve a la posición inicial. Repite el movimiento hacia el lado izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0096-i4JkUaL.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0096-i4JkUaL.gif'),
('0098', 'barbell side split squat', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los trapecios. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una posición de sentadilla, flexionando las rodillas y las caderas. Al bajar, empuja las rodillas hacia los lados y mantén el peso sobre los talones. Baja hasta que los muslos queden paralelos al suelo, luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0098-W31mMjd.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0098-W31mMjd.gif'),
('0097', 'barbell side split squat v. 2', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta una barra sobre la parte superior de la espalda, apoyándola en los hombros. Da un paso grande hacia el lado con el pie derecho, manteniendo el pie izquierdo fijo en el suelo. Flexiona la rodilla derecha y baja el cuerpo hacia una posición de sentadilla, manteniendo el pecho elevado y la espalda recta. Empuja con el talón derecho para regresar a la posición inicial. Repite hacia el otro lado, dando el paso con el pie izquierdo. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0097-HUEqZ1y.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0097-HUEqZ1y.gif'),
('1756', 'barbell single leg deadlift', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de las caderas, sujetando una barra frente a los muslos con agarre prono. Traslada el peso hacia el pie izquierdo y levanta el pie derecho ligeramente del suelo. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y la pierna derecha extendida detrás de ti para el equilibrio. Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada. Haz una pausa breve en la posición más baja, luego activa los glúteos y los isquiotibiales para levantar el torso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1756-gEyURal.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1756-gEyURal.gif'),
('0099', 'barbell single leg split squat', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con una pierna, manteniendo el torso erguido. Baja el cuerpo flexionando la rodilla delantera y la cadera, mientras mantienes la pierna trasera recta. Continúa bajando hasta que el muslo delantero quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón delantero para volver a la posición inicial. Repite el número de repeticiones deseado, luego cambia de pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0099-gGNQmVt.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0099-gGNQmVt.gif'),
('2799', 'barbell sitted alternate leg raise', 'waist', 'barbell', 'abs', 'hip flexors', '{"hip flexors"}', 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Manteniendo las piernas rectas, levanta una pierna lo más alto posible mientras mantienes la otra pierna en el suelo. Baja la pierna elevada y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2799-G7xoEzr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2799-G7xoEzr.gif'),
('2800', 'barbell sitted alternate leg raise (female)', 'waist', 'barbell', 'abs', 'hip flexors', '{"hip flexors","quadriceps"}', 'Siéntate en un banco con la espalda recta y sujeta una barra sobre los muslos. Coloca las manos a los lados del banco para apoyarte. Manteniendo las piernas rectas, levanta una pierna lo más alto posible manteniéndola paralela al suelo. Baja la pierna y repite con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2800-BCs0G2F.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2800-BCs0G2F.gif'),
('0100', 'barbell skier', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","core"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente a los muslos con un agarre pronado. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Levanta simultáneamente la barra hacia los hombros mientras saltas ligeramente del suelo. Al llegar a la parte más alta del movimiento, invierte rápidamente el movimiento y baja la barra de nuevo a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0100-4Leypho.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0100-4Leypho.gif'),
('0101', 'barbell speed squat', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros, con los dedos de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si te sentaras en una silla. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Empuja con los talones para volver a ponerte de pie, contrayendo los glúteos en la parte más alta. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0101-euI1BwR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0101-euI1BwR.gif'),
('2810', 'barbell split squat v. 2', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Da un paso grande hacia adelante con el pie derecho, manteniendo el torso erguido. Baja el cuerpo flexionando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo. Haz una pausa breve, luego empuja con el talón derecho para volver a la posición inicial. Repite con la pierna izquierda adelante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2810-HBYyX94.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2810-HBYyX94.gif'),
('0102', 'barbell squat (on knees)', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Comienza arrodillado en el suelo con las rodillas separadas a la altura de las caderas y las puntas de los pies apuntando hacia adelante. Coloca una barra sobre los hombros, sujetándola con agarre prono y las manos un poco más separadas que el ancho de los hombros. Activa el core y mantén el pecho elevado mientras bajas lentamente el cuerpo flexionando las rodillas, manteniendo la espalda recta. Continúa bajando hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0102-oR7O9LW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0102-oR7O9LW.gif'),
('2798', 'barbell squat jump step rear lunge', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Empieza de pie con los pies separados a la altura de los hombros, sujetando una barra sobre la parte superior de la espalda. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Impúlsate explosivamente hacia arriba, saltando del suelo lo más alto que puedas. Aterriza suavemente sobre los pies y de inmediato retrocede con una pierna hacia una zancada inversa. Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta. Empuja con el talón delantero para volver a la posición inicial. Repite la secuencia de salto y zancada con la otra pierna. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2798-RYcV1kH.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2798-RYcV1kH.gif'),
('0103', 'barbell standing ab rollerout', 'waist', 'barbell', 'abs', 'shoulders', '{"shoulders","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con ambas manos frente a los muslos. Activa el core y enrolla lentamente la barra hacia el suelo, manteniendo la espalda recta y los brazos extendidos. Continúa enrollando la barra hacia adelante hasta que el cuerpo esté completamente extendido y las manos queden justo sobre la cabeza. Haz una pausa breve, luego enrolla lentamente la barra de vuelta hacia los muslos, manteniendo el control y el core activado. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0103-xnInPfE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0103-xnInPfE.gif'),
('0104', 'barbell standing back wrist curl', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Apoya la barra sobre el dorso de las manos con las palmas hacia abajo y los dedos apuntando hacia el cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona las muñecas hacia arriba lo más posible. Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0104-2qTvJAZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0104-2qTvJAZ.gif'),
('0105', 'barbell standing bradford press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra frente a los hombros con agarre prono. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0105-dCPESfR.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0105-dCPESfR.gif'),
('1372', 'barbell standing calf raise', 'lower legs', 'barbell', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, apoyándote solo en las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1372-8ozhUIZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1372-8ozhUIZ.gif'),
('0106', 'barbell standing close grip curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas. Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento. Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0106-4dUn2iv.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0106-4dUn2iv.gif'),
('1456', 'barbell standing close grip military press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, manos un poco más juntas que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos cerca del cuerpo. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de nuevo a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1456-wdRZISl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1456-wdRZISl.gif'),
('2414', 'barbell standing concentration curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con una mano, con la palma hacia arriba. Apoya la otra mano sobre el muslo para mayor estabilidad. Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia el hombro. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente el peso de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2414-vsMcDi9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2414-vsMcDi9.gif'),
('0107', 'barbell standing front raise over head', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una barra frente a los muslos con agarre prono. Mantén la espalda recta y activa el core. Levanta lentamente la barra frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que la barra quede ligeramente por encima del nivel de los hombros. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0107-S8mo30S.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0107-S8mo30S.gif'),
('0108', 'barbell standing leg calf raise', 'lower legs', 'barbell', 'calves', 'hamstrings', '{"hamstrings","glutes"}', 'Ponte de pie con los pies separados a la altura de los hombros y coloca una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, usando las pantorrillas. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0108-rGwhJ5o.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0108-rGwhJ5o.gif'),
('0109', 'barbell standing overhead triceps extension', 'upper arms', 'barbell', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono. Levanta la barra por encima de la cabeza, extendiendo completamente los brazos. Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos. Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0109-dZl9Q27.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0109-dZl9Q27.gif'),
('0110', 'barbell standing reverse grip curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba. Mantén los codos cerca del torso y los brazos superiores quietos. Exhala y flexiona el peso contrayendo los bíceps, llevando la barra lo más cerca posible de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0110-LWuA3aZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0110-LWuA3aZ.gif'),
('0111', 'barbell standing rocking leg calf raise', 'lower legs', 'barbell', 'calves', 'hamstrings', '{"hamstrings","quadriceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra sobre la parte superior de la espalda. Levanta los talones del suelo lo más alto posible, manteniendo el equilibrio sobre las puntas de los pies. Baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0111-6HiHHe0.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0111-6HiHHe0.gif'),
('0112', 'barbell standing twist', 'waist', 'barbell', 'abs', 'obliques', '{"obliques","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra frente al pecho con ambas manos, palmas hacia abajo. Activa el core y mantén la espalda recta durante todo el ejercicio. Gira lentamente el torso hacia la derecha, pivotando sobre los pies y las caderas, mientras mantienes estable la parte inferior del cuerpo. Haz una pausa por un momento al final de la rotación, luego regresa lentamente a la posición inicial. Repite el giro hacia el lado izquierdo. Continúa alternando los giros el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0112-yQe5HpE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0112-yQe5HpE.gif'),
('1629', 'barbell standing wide grip biceps curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros. Mantén la espalda recta y los codos cerca del torso. Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos. Haz una pausa breve en la parte alta, apretando los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1629-faHKVkK.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1629-faHKVkK.gif'),
('1457', 'barbell standing wide military press', 'shoulders', 'barbell', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Levanta la barra hasta la altura de los hombros, manteniendo los codos ligeramente por delante de la barra. Empuja la barra por encima de la cabeza, extendiendo completamente los brazos. Baja la barra de vuelta a la altura de los hombros y repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1457-Kyd9Rz5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1457-Kyd9Rz5.gif'),
('0113', 'barbell standing wide-grip curl', 'upper arms', 'barbell', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue a la longitud del brazo frente a los muslos, con las palmas mirando hacia afuera del cuerpo. Manteniendo los brazos superiores quietos, exhala y flexiona la barra hacia arriba contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0113-NdIb5Z1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0113-NdIb5Z1.gif'),
('0114', 'barbell step-up', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie frente a un banco o escalón con una barra apoyada en la parte superior de la espalda. Coloca un pie sobre el banco o escalón, asegurándote de que todo el pie esté en contacto con la superficie. Empuja con el talón y sube al banco o escalón, extendiendo completamente la cadera y la rodilla. Haz una pausa breve en la parte más alta, luego baja de vuelta a la posición inicial. Repite con la pierna contraria. Continúa alternando las piernas durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0114-Kxquu2E.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0114-Kxquu2E.gif'),
('0115', 'barbell stiff leg good morning', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios. Manteniendo la espalda recta, inclínate hacia adelante desde las caderas, empujando los glúteos hacia atrás. Baja el torso hasta que quede paralelo al suelo, sintiendo un estiramiento en los isquiotibiales. Activa los glúteos y los isquiotibiales para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0115-JrOHAZc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0115-JrOHAZc.gif'),
('0116', 'barbell straight leg deadlift', 'upper legs', 'barbell', 'hamstrings', 'glutes', '{"glutes","lower back"}', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies apuntando hacia delante. Sujeta la barra con un agarre pronado, manos un poco más separadas que el ancho de los hombros. Flexiona las caderas y baja la barra hacia el suelo, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Baja la barra hasta que sientas un estiramiento en los isquiotibiales. Activa los isquiotibiales y los glúteos para levantar la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0116-hrVQWvE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0116-hrVQWvE.gif'),
('0117', 'barbell sumo deadlift', 'upper legs', 'barbell', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","lower back"}', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies hacia afuera. Coloca una barra en el suelo frente a ti, centrada entre los pies. Flexiona las rodillas y baja las caderas, manteniendo la espalda recta y el pecho elevado, para sujetar la barra con agarre prono. Activa el core y empuja con los talones para levantar la barra del suelo, extendiendo las caderas y las rodillas simultáneamente. Al levantar, mantén el pecho elevado y la espalda recta, y empuja las caderas hacia adelante para activar completamente los glúteos. Haz una pausa breve en la parte más alta, luego baja lentamente la barra de vuelta a la posición inicial, manteniendo el control durante todo el movimiento. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0117-KgI0tqW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0117-KgI0tqW.gif'),
('3305', 'barbell thruster', 'shoulders', 'barbell', 'delts', 'quadriceps', '{"quadriceps","glutes","hamstrings","core"}', 'Comienza de pie con los pies separados a la altura de los hombros, sujetando una barra a la altura de los hombros con agarre prono. Baja a una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Al llegar a la parte más baja de la sentadilla, empuja explosivamente con los talones para ponerte de pie, presionando simultáneamente la barra por encima de la cabeza. Baja la barra de nuevo a la altura de los hombros mientras vuelves a bajar a la posición de sentadilla. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3305-f7Y9eDZ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3305-f7Y9eDZ.gif'),
('0120', 'barbell upright row', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta y el core activado, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0120-UDlhcO8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0120-UDlhcO8.gif'),
('0119', 'barbell upright row v. 2', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0119-83HoW9X.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0119-83HoW9X.gif'),
('0121', 'barbell upright row v. 3', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos un poco más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo el core activado y la espalda recta, exhala mientras levantas la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala mientras bajas lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0121-fI18Rbc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0121-fI18Rbc.gif'),
('0122', 'barbell wide bench press', 'chest', 'barbell', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Agarra la barra con un agarre amplio, un poco más ancho que la separación de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos ligeramente abiertos hacia afuera. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0122-JsKq9so.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0122-JsKq9so.gif'),
('1258', 'barbell wide reverse grip bench press', 'chest', 'barbell', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco. Sujeta la barra con un agarre supino amplio, un poco más separado que el ancho de los hombros. Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos. Baja la barra lentamente hacia el pecho, manteniendo los codos pegados al cuerpo y las muñecas rectas. Haz una pausa breve cuando la barra toque el pecho y luego empújala de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1258-945zpRg.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1258-945zpRg.gif'),
('0124', 'barbell wide squat', 'upper legs', 'barbell', 'quads', 'glutes', '{"glutes","hamstrings","calves"}', 'Ponte de pie con los pies más separados que el ancho de los hombros, con las puntas de los pies ligeramente hacia afuera. Sujeta la barra sobre la parte superior de la espalda, apoyándola en los trapecios o los deltoides posteriores. Activa el core y mantén el pecho elevado mientras bajas el cuerpo hacia una sentadilla, empujando las caderas hacia atrás y flexionando las rodillas. Baja hasta que los muslos queden paralelos al suelo, o tan abajo como puedas hacerlo cómodamente. Haz una pausa por un momento en la parte inferior, luego empuja con los talones para regresar a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0124-s7HX1BY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0124-s7HX1BY.gif'),
('0123', 'barbell wide-grip upright row', 'shoulders', 'barbell', 'delts', 'traps', '{"traps","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono, manos más separadas que el ancho de los hombros. Deja que la barra cuelgue frente a los muslos, con los brazos completamente extendidos. Manteniendo la espalda recta, exhala y levanta la barra en línea recta hacia la barbilla, guiando el movimiento con los codos. Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0123-RgJDRR1.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0123-RgJDRR1.gif'),
('0126', 'barbell wrist curl', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies planos en el suelo y los antebrazos apoyados sobre los muslos, sujetando una barra con agarre supino. Deja que la barra ruede hacia las puntas de los dedos, manteniendo las muñecas rectas. Enrolla lentamente la barra hacia los antebrazos flexionando las muñecas. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0126-82LxxkW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0126-82LxxkW.gif'),
('0125', 'barbell wrist curl v. 2', 'lower arms', 'barbell', 'forearms', 'biceps', '{"biceps","brachialis"}', 'Siéntate en un banco con los pies planos sobre el suelo y las rodillas flexionadas. Sujeta una barra con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros. Apoya los antebrazos sobre los muslos, dejando que las muñecas cuelguen del borde. Flexiona lentamente las muñecas hacia arriba, llevando la barra hacia los antebrazos. Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0125-6kSxYnw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0125-6kSxYnw.gif'),
('0127', 'barbell zercher squat', 'upper legs', 'barbell', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves","core"}', 'Ponte de pie con los pies separados a la altura de los hombros y los dedos de los pies ligeramente hacia afuera. Sujeta la barra en el pliegue de los codos, con las manos agarrando la barra para mayor estabilidad. Activa el core y mantén el pecho elevado mientras bajas las caderas hacia atrás y hacia abajo en una posición de sentadilla. Mantén las rodillas alineadas con los dedos de los pies y el peso sobre los talones. Haz una pausa breve en la parte baja de la sentadilla y luego empuja con los talones para volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0127-LSTChY9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0127-LSTChY9.gif'),
('3212', 'basic toe touch (male)', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros y los brazos a los costados. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y las rodillas ligeramente flexionadas. Extiende las manos hacia las puntas de los pies, manteniendo las piernas lo más rectas posible. Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3212-BbfB8Gb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3212-BbfB8Gb.gif'),
('0128', 'battling ropes', 'shoulders', 'rope', 'delts', 'forearms', '{"forearms","core"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta un extremo de la cuerda en cada mano, con las palmas mirándose entre sí. Levanta los brazos hasta la altura de los hombros, manteniendo los codos ligeramente flexionados. Comienza a hacer ondas alternas con las cuerdas, levantando y bajando rápidamente cada brazo. Continúa durante el tiempo o el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0128-RJa4tCo.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0128-RJa4tCo.gif'),
('3360', 'bear crawl', 'cardio', 'body weight', 'cardiovascular system', 'core', '{"core","shoulders","triceps"}', 'Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas. Levanta las rodillas ligeramente del suelo, manteniendo la espalda plana y el core activado. Mueve la mano derecha y el pie izquierdo hacia adelante simultáneamente, seguido de la mano izquierda y el pie derecho. Continúa avanzando a gatas, alternando los movimientos de manos y pies. Mantén un ritmo constante y el core firme durante todo el ejercicio. Continúa durante la distancia o el tiempo deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3360-0Yz8WdV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3360-0Yz8WdV.gif'),
('1259', 'behind head chest stretch', 'chest', 'assisted', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ponte de pie con la espalda recta y los pies separados a la altura de los hombros. Entrelaza los dedos detrás de la cabeza con los codos apuntando hacia afuera. Junta lentamente los omóplatos y empuja el pecho hacia adelante. Mantén el estiramiento durante 15-30 segundos. Suelta el estiramiento y repite cuantas veces lo desees.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1259-QoHIhPl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1259-QoHIhPl.gif'),
('0129', 'bench dip (knees bent)', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas. Desliza los glúteos fuera del banco y estira las piernas frente a ti, manteniendo los talones en el suelo. Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco. Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0129-RrLske5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0129-RrLske5.gif'),
('1399', 'bench dip on floor', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante. Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos. Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo. Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1399-9RT8oQW.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1399-9RT8oQW.gif'),
('0130', 'bench hip extension', 'upper legs', 'body weight', 'glutes', 'hamstrings', '{"hamstrings"}', 'Siéntate en un banco con la espalda contra el banco y los pies planos en el suelo. Coloca las manos sobre el banco para apoyarte. Activa los glúteos y los isquiotibiales, luego levanta las caderas del banco hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0130-u27Kcdz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0130-u27Kcdz.gif'),
('3019', 'bench pull-ups', 'back', 'body weight', 'lats', 'biceps', '{"biceps","forearms"}', 'Colócate debajo de una barra o una superficie horizontal resistente que esté a la altura del pecho. Sujeta la barra o la superficie con agarre prono, un poco más separado que el ancho de los hombros. Cuélgate con los brazos completamente extendidos y el cuerpo recto. Lleva el pecho hacia la barra o la superficie juntando los omóplatos y flexionando los codos. Continúa tirando hasta que la barbilla quede por encima de la barra o la superficie. Baja de nuevo a la posición inicial con control. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3019-mExgrF9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3019-mExgrF9.gif'),
('3639', 'bent knee lying twist (male)', 'upper legs', 'body weight', 'glutes', 'obliques', '{"obliques","hip flexors"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Extiende los brazos hacia los lados, perpendiculares al cuerpo. Manteniendo las rodillas juntas, bájalas lentamente hacia un lado, intentando tocar el suelo con las rodillas. Haz una pausa breve, luego activa el core y levanta lentamente las rodillas de vuelta a la posición inicial. Repite el movimiento hacia el otro lado. Continúa alternando lados durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3639-6sYyrRX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3639-6sYyrRX.gif'),
('1770', 'biceps leg concentration curl', 'upper arms', 'body weight', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco con las piernas separadas y los pies planos en el suelo. Sujeta una mancuerna con una mano y coloca el codo en la parte interna del muslo, justo por encima de la rodilla. Con la palma hacia arriba, flexiona la mancuerna hacia el hombro manteniendo el brazo superior quieto. Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1770-sJFIDIp.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1770-sJFIDIp.gif'),
('0139', 'biceps narrow pull-ups', 'upper arms', 'body weight', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo. Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0139-50BETrz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0139-50BETrz.gif'),
('0140', 'biceps pull-up', 'upper arms', 'body weight', 'biceps', 'forearms', '{"forearms","shoulders"}', 'Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros. Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra. Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0140-guT8YnS.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0140-guT8YnS.gif'),
('0137', 'body-up', 'upper arms', 'body weight', 'triceps', 'chest', '{"chest","shoulders"}', 'Comienza colocando las manos sobre una superficie elevada, como un banco o unas barras paralelas, con las palmas hacia abajo y los dedos apuntando hacia adelante. Extiende las piernas frente a ti, manteniendo los talones en el suelo y el cuerpo recto. Baja el cuerpo flexionando los codos, manteniéndolos cerca del cuerpo, hasta que los brazos superiores queden paralelos al suelo. Haz una pausa breve, luego empuja con las palmas para extender los brazos y levantar el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0137-U6G2gk9.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0137-U6G2gk9.gif'),
('3543', 'bodyweight drop jump squat', 'upper legs', 'body weight', 'glutes', 'quadriceps', '{"quadriceps","hamstrings","calves"}', 'Ponte de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y empujando las caderas hacia atrás. Salta hacia arriba explosivamente, extendiendo las caderas, las rodillas y los tobillos. Mientras estás en el aire, junta rápidamente los pies. Aterriza suavemente sobre las puntas de los pies y de inmediato vuelve a bajar a una posición de sentadilla. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3543-wfotm7S.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3543-wfotm7S.gif'),
('3544', 'bodyweight incline side plank', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","shoulders"}', 'Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra. Coloca el antebrazo en el suelo justo debajo del hombro, con el codo flexionado en un ángulo de 90 grados. Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies. Mantén esta posición durante el tiempo deseado. Baja las caderas de nuevo al suelo y repite hacia el otro lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3544-5VXmnV5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3544-5VXmnV5.gif'),
('1771', 'bodyweight kneeling triceps extension', 'upper arms', 'body weight', 'triceps', 'shoulders', '{"shoulders","chest"}', 'Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas. Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante. Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones. Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo. Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1771-s0HKO2I.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1771-s0HKO2I.gif'),
('1769', 'bodyweight side lying biceps curl', 'upper arms', 'body weight', 'biceps', 'forearms', '{"forearms"}', 'Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo. Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro. Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1769-gscGLOU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1769-gscGLOU.gif'),
('3168', 'bodyweight squatting row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando un objeto resistente o un entrenador de suspensión con los brazos extendidos. Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies. Desde la posición de sentadilla, tira del cuerpo hacia arriba en dirección al objeto o al entrenador de suspensión, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3168-3xK09Sk.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3168-3xK09Sk.gif'),
('3167', 'bodyweight squatting row (with towel)', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros, sujetando una toalla frente a ti con las palmas hacia abajo. Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado. Mientras bajas a la sentadilla, tira simultáneamente de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más baja de la sentadilla, luego vuelve lentamente a la posición inicial mientras extiendes los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3167-BReCuOn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3167-BReCuOn.gif'),
('1373', 'bodyweight standing calf raise', 'lower legs', 'body weight', 'calves', 'ankles', '{"ankles","feet"}', 'Ponte de pie con los pies separados a la altura de los hombros, con las puntas de los pies apuntando hacia adelante. Coloca las manos sobre una pared o superficie estable para mantener el equilibrio. Levanta lentamente los talones del suelo, llevando el peso del cuerpo hacia las puntas de los pies. Haz una pausa breve en la parte alta y luego baja lentamente los talones de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1373-bJYHBIN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1373-bJYHBIN.gif'),
('3156', 'bodyweight standing close-grip one arm row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna en una mano con agarre neutro. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo y juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3156-v2DfH14.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3156-v2DfH14.gif'),
('3158', 'bodyweight standing close-grip row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el core activado. Extiende los brazos rectos frente a ti, sujetando la barra o las agarraderas con un agarre cerrado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente y vuelve a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3158-tig3PXb.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3158-tig3PXb.gif'),
('3162', 'bodyweight standing one arm row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una mancuerna con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Deja que la mancuerna cuelgue recta frente a ti, con el brazo completamente extendido. Tira de la mancuerna hacia el pecho, manteniendo el codo cerca del cuerpo. Junta los omóplatos en la parte superior del movimiento. Baja la mancuerna de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3162-xbkPfaw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3162-xbkPfaw.gif'),
('3161', 'bodyweight standing one arm row (with towel)', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros, las rodillas ligeramente flexionadas, y sujeta una toalla con una mano. Inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el core activado. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa breve en la parte más alta, luego baja lentamente la toalla de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia al otro brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3161-O4oIqQD.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3161-O4oIqQD.gif'),
('3166', 'bodyweight standing row', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta una barra o las agarraderas con agarre prono, palmas hacia abajo. Mantén la espalda recta y el core activado. Tira de la barra o las agarraderas hacia el cuerpo, juntando los omóplatos. Haz una pausa breve en la parte alta del movimiento. Suelta lentamente y extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3166-wd4ds3s.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3166-wd4ds3s.gif'),
('3165', 'bodyweight standing row (with towel)', 'back', 'body weight', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta una toalla frente a ti con ambas manos. Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta. Tira de la toalla hacia el pecho, juntando los omóplatos. Haz una pausa por un momento en la parte superior, luego suelta lentamente la tensión y regresa a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3165-uTv34oq.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3165-uTv34oq.gif'),
('0138', 'bottoms-up', 'waist', 'body weight', 'abs', 'obliques', '{"obliques","hip flexors"}', 'Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados. Flexiona las rodillas y llévalas hacia el pecho, manteniendo los pies fuera del suelo. Activando el abdomen, levanta las caderas del suelo, llevando las rodillas hacia la cabeza. Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0138-CI6baTY.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0138-CI6baTY.gif'),
('1374', 'box jump down with one leg stabilization', 'lower legs', 'body weight', 'calves', 'quadriceps', '{"quadriceps","hamstrings","glutes"}', 'Ponte de pie frente a una caja o plataforma con los pies separados a la altura de los hombros. Flexiona las rodillas y salta sobre la caja, aterrizando suavemente con un pie sobre la caja y el otro pie colgando del borde. Estabilízate sobre la caja con el pie que está sobre ella, mientras mantienes el otro pie fuera del suelo. Mantén esta posición durante unos segundos, activando los músculos de la pantorrilla para conservar el equilibrio. Baja lentamente con el pie que está sobre la caja, volviendo a la posición inicial. Repite el ejercicio con la otra pierna.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1374-iPm26QU.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1374-iPm26QU.gif'),
('2466', 'bridge - mountain climber (cross body)', 'waist', 'body weight', 'abs', 'glutes', '{"glutes","quadriceps","hamstrings","shoulders","triceps"}', 'Comienza en una posición de plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta. Activa el core y levanta el pie derecho del suelo, llevando la rodilla derecha hacia el codo izquierdo. Vuelve a colocar el pie derecho en la posición inicial y repite el movimiento llevando el pie izquierdo hacia el codo derecho. Continúa alternando los lados, moviéndote a un ritmo controlado. Mantén las caderas niveladas y evita levantarlas demasiado alto o dejarlas caer demasiado bajo. Mantén un patrón de respiración constante durante todo el ejercicio. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/2466-9c6T1YX.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/2466-9c6T1YX.gif'),
('1160', 'burpee', 'cardio', 'body weight', 'cardiovascular system', 'quadriceps', '{"quadriceps","hamstrings","calves","shoulders","chest"}', 'Comienza de pie con los pies separados a la altura de los hombros. Baja el cuerpo hacia una posición de sentadilla flexionando las rodillas y colocando las manos en el suelo frente a ti. Lleva los pies hacia atrás de una patada hasta una posición de flexión de brazos. Realiza una flexión de brazos, manteniendo el cuerpo en línea recta. Salta con los pies de vuelta a la posición de sentadilla. Salta hacia arriba explosivamente, llevando los brazos por encima de la cabeza. Aterriza suavemente y baja de inmediato a una posición de sentadilla para comenzar la siguiente repetición.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1160-dK9394r.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1160-dK9394r.gif'),
('0870', 'butt-ups', 'waist', 'body weight', 'abs', 'hip flexors', '{"hip flexors","lower back"}', 'Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo. Coloca las manos a los lados, con las palmas hacia abajo. Activando el abdomen, levanta las piernas del suelo, llevando las rodillas hacia el pecho. En la parte más alta del movimiento, contrae el abdomen y haz una pausa breve. Baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0870-qcNN2FN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0870-qcNN2FN.gif'),
('1494', 'butterfly yoga pose', 'upper legs', 'body weight', 'adductors', 'hamstrings', '{"hamstrings","groin"}', 'Siéntate en el suelo con las piernas extendidas frente a ti. Flexiona las rodillas y junta las plantas de los pies, dejando que las rodillas caigan hacia los lados. Sujétate los tobillos o los pies con las manos. Siéntate erguido y alarga la columna. Presiona suavemente las rodillas hacia el suelo, sintiendo un estiramiento en la parte interna de los muslos. Mantén esta posición durante unas cuantas respiraciones. Para liberar, lleva lentamente las rodillas hacia arriba de nuevo y extiende las piernas.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1494-bWlZvXh.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1494-bWlZvXh.gif'),
('0148', 'cable alternate shoulder press', 'shoulders', 'cable', 'delts', 'triceps', '{"triceps","upper back"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta las agarraderas de la máquina de cable con agarre prono. Coloca las manos a la altura de los hombros, con las palmas mirando hacia adelante. Mantén el core activado y la espalda recta. Empuja una agarradera hacia arriba y hacia adelante hasta que el brazo quede completamente extendido. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera de vuelta a la posición inicial. Repite con el otro brazo. Alterna entre los brazos el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0148-KHPZL0b.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0148-KHPZL0b.gif'),
('0149', 'cable alternate triceps extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados. Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite con el brazo izquierdo. Continúa alternando los brazos durante el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0149-Gchi5Tr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0149-Gchi5Tr.gif'),
('3235', 'cable assisted inverse leg curl', 'upper legs', 'cable', 'hamstrings', 'glutes', '{"glutes","calves"}', 'Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja. Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos. Sujétate de las agarraderas del banco para mantener la estabilidad. Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas. Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales. Inhala y baja lentamente las piernas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/3235-zHEpuuc.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/3235-zHEpuuc.gif'),
('0150', 'cable bar lateral pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Ajusta la polea del cable a una posición alta y coloca una barra recta. Siéntate frente a la máquina de cable con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros. Inclínate ligeramente hacia atrás y mantén el pecho elevado, conservando un ligero arco en la zona lumbar. Tira de la barra hacia el pecho, guiando el movimiento con los codos y juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0150-eYnzaCm.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0150-eYnzaCm.gif'),
('0151', 'cable bench press', 'chest', 'cable', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la máquina de cable a la altura del pecho y coloca las agarraderas. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia adelante para crear tensión en los cables. Coloca los pies firmemente en el suelo y activa el core. Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados. Empuja las agarraderas hacia adelante, extendiendo completamente los brazos frente a ti. Haz una pausa breve, luego invierte lentamente el movimiento, llevando las manos de vuelta a la altura de los hombros. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0151-7xI5MXA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0151-7xI5MXA.gif'),
('1630', 'cable close grip curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Coloca una barra recta en una máquina de cable con polea baja. Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la barra con agarre supino, manos separadas a la altura de los hombros. Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio. Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1630-BCGQ6J5.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1630-BCGQ6J5.gif'),
('1631', 'cable concentration curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo. Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps. Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1631-NvfE43H.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1631-NvfE43H.gif'),
('0152', 'cable concentration extension (on knee)', 'upper arms', 'cable', 'triceps', 'forearms', '{"forearms"}', 'Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo. Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha. Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla. Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial. Repite el número de repeticiones deseado, luego cambia de lado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0152-Db7eEgw.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0152-Db7eEgw.gif'),
('0153', 'cable cross-over lateral pulldown', 'back', 'cable', 'lats', 'biceps', '{"biceps","rhomboids","rear deltoids"}', 'Coloca una agarradera de cable en cada lado de una máquina de cable a la altura de los hombros. Ponte de pie en el centro de la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con agarre prono y da un paso hacia atrás para crear tensión en los cables. Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado. Tira de las agarraderas hacia abajo y a través del cuerpo, juntando los omóplatos. Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0153-OQ1otBN.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0153-OQ1otBN.gif'),
('0154', 'cable cross-over revers fly', 'shoulders', 'cable', 'delts', 'rhomboids', '{"rhomboids","trapezius"}', 'Coloca una agarradera en D en cada cable de polea baja y ponte de pie en el centro de la máquina de cable cruzado. Sujeta las agarraderas con agarre prono (palmas hacia abajo) y da un paso hacia adelante, colocando los pies separados a la altura de los hombros. Flexiona ligeramente las rodillas e inclínate hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen activado. Con los brazos extendidos hacia los lados y ligeramente flexionados en los codos, exhala y junta los omóplatos mientras tiras de los cables hacia atrás y hacia arriba en un movimiento de apertura inversa. Haz una pausa breve en el punto máximo de contracción, luego inhala y vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0154-aqvSOQE.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0154-aqvSOQE.gif'),
('0155', 'cable cross-over variation', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ajusta las poleas del cable a la altura del pecho. Ponte de pie en el centro de la máquina de cable con un pie delante del otro. Sujeta las agarraderas con las palmas hacia abajo y los brazos extendidos hacia los lados. Da un paso hacia adelante, manteniendo los brazos ligeramente flexionados. Con una ligera flexión en los codos, junta las manos frente al pecho. Haz una pausa breve, luego vuelve lentamente los brazos a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0155-0CXGHya.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0155-0CXGHya.gif'),
('0868', 'cable curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba. Mantén los codos cerca de los costados y los brazos superiores quietos. Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0868-G08RZcQ.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0868-G08RZcQ.gif'),
('0157', 'cable deadlift', 'upper legs', 'cable', 'glutes', 'hamstrings', '{"hamstrings","quadriceps","lower back"}', 'Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros. Flexiona las caderas y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo. Sujeta las agarraderas del cable con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás. Activa los glúteos y los isquiotibiales para levantar las agarraderas del cable, extendiendo las caderas y poniéndote de pie. Haz una pausa breve en la parte más alta, luego baja lentamente las agarraderas del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0157-eGDudUV.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0157-eGDudUV.gif'),
('0158', 'cable decline fly', 'chest', 'cable', 'pectorals', 'shoulders', '{"shoulders","triceps"}', 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta las agarraderas con las palmas hacia adelante y los brazos extendidos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0158-7saC5zz.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0158-7saC5zz.gif'),
('1260', 'cable decline one arm press', 'chest', 'cable', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la máquina de cable a una posición declinada. Ponte de pie de espaldas a la máquina y sujeta la agarradera con una mano. Colócate con la espalda contra el banco declinado y el brazo extendido recto frente a ti. Flexiona el codo y baja la agarradera hacia el pecho, manteniendo el brazo superior quieto. Haz una pausa breve en la parte más baja, luego empuja la agarradera de vuelta hacia la posición inicial. Repite el número de repeticiones deseado, luego cambia de brazo.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1260-KHGNa16.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1260-KHGNa16.gif'),
('1261', 'cable decline press', 'chest', 'cable', 'pectorals', 'triceps', '{"triceps","shoulders"}', 'Ajusta la máquina de cable a una posición declinada. Siéntate en el banco declinado frente a la máquina de cable. Sujeta las agarraderas con agarre prono y colócalas a la altura del pecho. Mantén los pies planos en el suelo y la espalda firmemente apoyada en el banco. Exhala y empuja las agarraderas alejándolas del cuerpo, extendiendo completamente los brazos. Haz una pausa breve al final del movimiento, contrayendo los músculos del pecho. Inhala y vuelve lentamente las agarraderas a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1261-2Pya1cP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1261-2Pya1cP.gif'),
('0159', 'cable decline seated wide-grip row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en el banco declinado frente a la máquina de cable con los pies firmemente colocados en los reposapiés. Sujeta el accesorio del cable con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el core activado. Tira del cable hacia la parte inferior del pecho, juntando los omóplatos. Haz una pausa breve en el punto máximo de la contracción, luego suelta lentamente el cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0159-kesXOpB.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0159-kesXOpB.gif'),
('1632', 'cable drag curl', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros. Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos. Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps. Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps. Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1632-dXz8zjF.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1632-dXz8zjF.gif'),
('0160', 'cable floor seated wide-grip row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","forearms"}', 'Siéntate en el suelo con las piernas extendidas y la espalda recta. Coloca una agarradera de cable en una polea baja y ubica la máquina de cable detrás de ti. Sujeta la agarradera con un agarre prono amplio, palmas hacia abajo. Inclínate ligeramente hacia atrás, manteniendo la espalda recta y el pecho elevado. Tira de la agarradera hacia la cintura, juntando los omóplatos. Haz una pausa breve en la parte más alta del movimiento, luego suelta lentamente la agarradera de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0160-veXwo0D.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0160-veXwo0D.gif'),
('0161', 'cable forward raise', 'shoulders', 'cable', 'delts', 'triceps', '{"triceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con agarre prono, palmas hacia abajo, y los brazos completamente extendidos frente a ti. Manteniendo los brazos rectos, levanta la agarradera del cable hasta la altura de los hombros. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0161-hvHhCv8.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0161-hvHhCv8.gif'),
('0162', 'cable front raise', 'shoulders', 'cable', 'delts', 'triceps', '{"triceps","forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0162-u2X71Np.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0162-u2X71Np.gif'),
('0164', 'cable front shoulder raise', 'shoulders', 'cable', 'delts', 'trapezius', '{"trapezius","biceps"}', 'Ponte de pie con los pies separados a la altura de los hombros y sujeta la agarradera del cable con agarre prono. Mantén la espalda recta y el core activado. Levanta la agarradera del cable frente a ti, manteniendo los brazos rectos y las palmas hacia abajo. Continúa levantando hasta que los brazos queden paralelos al suelo. Haz una pausa breve en la parte más alta, luego baja lentamente la agarradera del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0164-mTT3KLn.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0164-mTT3KLn.gif'),
('0165', 'cable hammer curl (with rope)', 'upper arms', 'cable', 'biceps', 'forearms', '{"forearms"}', 'Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas. Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos. Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps. Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros. Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps. Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0165-HPlPoQA.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0165-HPlPoQA.gif'),
('1722', 'cable high pulley overhead tricep extension', 'upper arms', 'cable', 'triceps', 'shoulders', '{"shoulders"}', 'Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina. Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza. Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil. Baja lentamente la cuerda detrás de la cabeza flexionando los codos. Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1722-1xHyxys.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1722-1xHyxys.gif'),
('0167', 'cable high row (kneeling)', 'back', 'cable', 'upper back', 'biceps', '{"biceps","shoulders"}', 'Sujeta una barra recta a una máquina de cable a la altura del pecho. Ponte de rodillas frente a la máquina de cable y agarra la barra con un agarre prono, con las manos separadas a la altura de los hombros. Siéntate sobre los talones, manteniendo la espalda recta y el core activado. Jala la barra hacia la parte superior del abdomen, apretando los omóplatos entre sí. Haz una pausa por un momento en la parte más alta del movimiento y luego suelta lentamente la barra de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0167-ZSJNetl.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0167-ZSJNetl.gif'),
('0168', 'cable hip adduction', 'upper legs', 'cable', 'adductors', 'glutes', '{"glutes","quadriceps"}', 'Sujeta el manguito de tobillo a tu tobillo y ponte de pie frente a la máquina de cable. Colócate lo suficientemente alejado de la máquina para que haya tensión en el cable. Coloca las manos sobre la máquina para apoyarte. Manteniendo la pierna recta, mueve lentamente la pierna por delante del cuerpo hacia la línea media. Haz una pausa por un momento al final del movimiento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0168-hBGWILP.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0168-hBGWILP.gif'),
('0169', 'cable incline bench press', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ajusta el banco a una inclinación de 45 grados. Sujeta las agarraderas del cable a las poleas altas. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo. Sujeta las agarraderas con un agarre prono y llévalas a la altura de los hombros. Empuja las agarraderas hacia adelante y hacia arriba hasta que los brazos queden completamente extendidos. Haz una pausa por un momento y luego baja lentamente las agarraderas de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0169-Vh0GsK4.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0169-Vh0GsK4.gif'),
('1318', 'cable incline bench row', 'back', 'cable', 'upper back', 'biceps', '{"biceps","rear deltoids"}', 'Coloca un banco inclinado a un ángulo de 45 grados y sujeta una agarradera de cable a la polea baja. Siéntate en el banco frente a la máquina de cable con los pies apoyados planos en el suelo y las rodillas ligeramente flexionadas. Sujeta la agarradera del cable con un agarre prono y extiende los brazos completamente frente a ti. Inclínate hacia adelante desde las caderas manteniendo la espalda recta y el core activado. Jala la agarradera del cable hacia el pecho retrayendo los omóplatos y flexionando los codos. Aprieta los músculos de la espalda en la parte más alta del movimiento y luego extiende lentamente los brazos de vuelta a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/1318-yaMIo4D.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/1318-yaMIo4D.gif'),
('0171', 'cable incline fly', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Ajusta la máquina de cable a una posición baja y sujeta las agarraderas. Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo. Sujeta las agarraderas con un agarre prono y extiende los brazos rectos frente a ti. Manteniendo una ligera flexión en los codos, abre los brazos hacia los lados con un movimiento controlado. Haz una pausa breve en la posición completamente extendida, luego vuelve lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0171-tBWXbIT.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0171-tBWXbIT.gif'),
('0170', 'cable incline fly (on stability ball)', 'chest', 'cable', 'pectorals', 'deltoids', '{"deltoids","triceps"}', 'Coloca un balón de estabilidad en un ángulo inclinado. Sujeta las agarraderas del cable a las poleas altas de una máquina de cable. Siéntate sobre el balón de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo. Sujeta las agarraderas del cable con un agarre prono, con las palmas hacia adelante. Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado. Con un movimiento controlado, lleva los brazos hacia los lados, manteniendo una ligera flexión en los codos. Continúa el movimiento hasta que los brazos queden paralelos al suelo. Haz una pausa por un momento, luego regresa lentamente a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0170-27NNGFr.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0170-27NNGFr.gif'),
('0172', 'cable incline pushdown', 'back', 'cable', 'lats', 'triceps', '{"triceps","shoulders"}', 'Sujeta una barra recta a una máquina de cable con polea alta. Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros. Sujeta la barra con un agarre prono, con las manos un poco más separadas que el ancho de los hombros. Inclínate ligeramente hacia adelante y mantén la espalda recta. Jala la barra hacia abajo en dirección a tus muslos extendiendo los codos. Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial. Repite el número de repeticiones deseado.', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/images/0172-1PK5Uo3.jpg', 'https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/main/videos/0172-1PK5Uo3.gif');
